values (1, CURRENT_TIMESTAMP, 'pxsystemuser', 'A data scientist uses data to understand and explain the phenomena around them, and help organizations make better decisions.', CURRENT_TIMESTAMP, 'pxsystemuser', 'Data Scientist', '0HY6DBASQX2LC');
values (2, CURRENT_TIMESTAMP, 'pxsystemuser', 'Developers are often natural problem solvers who possess strong analytical skills and the ability to think outside the box.', CURRENT_TIMESTAMP, 'pxsystemuser', 'Software Developer', '0HY6DBASQX3LC');
values (3, CURRENT_TIMESTAMP, 'pxsystemuser', 'Project managers have the responsibility of the planning, procurement and execution of a project, in any undertaking that has a defined scope, defined start and a defined finish; regardless of industry', CURRENT_TIMESTAMP, 'pxsystemuser', 'Project Manager', '0HY6DBASQX4LC');
values (4, CURRENT_TIMESTAMP, 'pxsystemuser', 'A data analyst is a person whose job is to gather and interpret data in order to solve a specific problem', CURRENT_TIMESTAMP, 'pxsystemuser', 'Data Analyst', '0HY6DBASQX5LC');
values (5, CURRENT_TIMESTAMP, 'pxsystemuser', 'A senior software developer whose main responsability is to lead a team made of multiple developers.', CURRENT_TIMESTAMP, 'pxsystemuser', 'Lead Software developer', '0HY6DBASQX6LC');
values (6, CURRENT_TIMESTAMP, 'pxsystemuser', 'Data engineers work in a variety of settings to build systems that collect, manage, and convert raw data into usable information for data scientists and business analysts to interpret.', CURRENT_TIMESTAMP, 'pxsystemuser', 'Data Engineer', '0HY6DBASQX7LC');
values (7, CURRENT_TIMESTAMP, 'pxsystemuser', 'An Agile coach helps scale Agile project management processes across multiple teams or throughout an entire organization.', CURRENT_TIMESTAMP, 'pxsystemuser', 'Agile coach', '0HY6DBASQX8LC');
values (8, CURRENT_TIMESTAMP, 'pxsystemuser', 'The Scrum Master is accountable for establishing Scrum. They do this by helping everyone understand Scrum theory and practice, both within the Scrum Team and the organization while serving the Scrum Team as well as the larger organization. ', CURRENT_TIMESTAMP, 'pxsystemuser', 'Scrum master', '0HY6DBASQX9LC');
values (9, CURRENT_TIMESTAMP, 'pxsystemuser', 'A Reporting Analyst is crucial to many organizations that rely on data to guide their decisions. A Reporting Analyst is in charge of collecting and analyzing data for a company', CURRENT_TIMESTAMP, 'pxsystemuser', 'Reporting Analyst', '0HY8DBASQX1LC');
values (10, CURRENT_TIMESTAMP, 'pxsystemuser', 'A database administrator, or DBA, is responsible for maintaining, securing, and operating databases and also ensures that data is correctly stored and retrieved', CURRENT_TIMESTAMP, 'pxsystemuser', 'Database Administrator', '0HY8DBASQX2LC');
values (11, CURRENT_TIMESTAMP, 'pxsystemuser', 'A chief technology officer (CTO) (also known as a chief technical officer or chief technologist) is an officer tasked with managing technical operations of an organization.', CURRENT_TIMESTAMP, 'pxsystemuser', 'Chief Technology Officer', '0HY8DBASQX3LC');
values (12, CURRENT_TIMESTAMP, 'pxsystemuser', 'Medical engineers combine their engineering and biological sciences knowledge to research and develop innovative solutions to medical problems.', CURRENT_TIMESTAMP, 'pxsystemuser', 'Medical Engineer', '0HY8DBASQX4ZT');

